package com.ultras.bans.service;
import com.ultras.bans.ULTRASBansPlugin; import org.bukkit.entity.Player; import org.bukkit.inventory.ItemStack; import java.io.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public final class JailInventoryService {private final ULTRASBansPlugin p;private final Map<UUID,ItemStack[]> cache=new ConcurrentHashMap<>();public JailInventoryService(ULTRASBansPlugin p){this.p=p;}public void capture(Player x){cache.put(x.getUniqueId(),concat(x.getInventory().getStorageContents(),x.getInventory().getArmorContents(),x.getInventory().getItemInOffHand()));x.getInventory().clear();}public void restore(Player x){ItemStack[] a=cache.remove(x.getUniqueId());if(a==null)return;int n=x.getInventory().getStorageContents().length;ItemStack[] st=Arrays.copyOfRange(a,0,n);ItemStack[] ar=Arrays.copyOfRange(a,n,n+4);x.getInventory().setStorageContents(st);x.getInventory().setArmorContents(ar);x.getInventory().setItemInOffHand(a[a.length-1]);}private ItemStack[] concat(ItemStack[] a,ItemStack[] b,ItemStack c){ItemStack[] r=Arrays.copyOf(a,a.length+b.length+1);System.arraycopy(b,0,r,a.length,b.length);r[r.length-1]=c;return r;}}
